import numpy as np, random, copy, time, scipy.sparse as sp, scipy.sparse.linalg as spla, logging
from reference import Task
logging.basicConfig(level=logging.ERROR)

def fast_eigs(A,k):
    N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    return spla.eigs(A, k=k, v0=v0, ncv=30, maxiter=N*50, tol=1e-8)

def solver(problem):
    A=problem['matrix']; k=problem['k'];
    try:
        vals, vecs = fast_eigs(A,k)
    except spla.ArpackNoConvergence as e:
        vals, vecs = e.eigenvalues, e.eigenvectors
        if vals.shape[0] < k:
            vals, vecs = spla.eigs(A,k=k,v0=np.ones(A.shape[0]), ncv=30, maxiter=A.shape[0]*200, tol=0)
    pairs=list(zip(vals, vecs.T)); pairs.sort(key=lambda p:-abs(p[0])); return [p[1] for p in pairs]

task=Task()
seeds=random.sample(range(1_000_000), 200)
fail=0
for s in seeds:
    prob=task.generate_problem(300, random_seed=s)
    sol=solver(copy.deepcopy(prob))
    if not task.is_solution(prob, sol):
        fail+=1
        print('fail', s)
        break
print('fails', fail)
