import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as spla, random, copy, logging
from reference import Task
logging.basicConfig(level=logging.ERROR)

def solve_ncv(problem, ncv):
    A=problem['matrix']; k=problem['k']; N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    vals, vecs = spla.eigs(A, k=k, v0=v0, maxiter=N*200, ncv=ncv)
    pairs=sorted(zip(vals, vecs.T), key=lambda p: -abs(p[0]))
    return [p[1] for p in pairs]

def test(ncv, num=60):
    task=Task();
    for seed in random.sample(range(1_000_000), num):
        prob=task.generate_problem(n=300, random_seed=seed)
        try:
            sol=solve_ncv(copy.deepcopy(prob), ncv)
        except Exception as e:
            print('exception',e); return False
        if not task.is_solution(prob, sol):
            print('fail seed', seed)
            return False
    return True

for ncv in [20,25,30,35,40]:
    print('ncv', ncv, test(ncv, num=30))
